"""
Thin wrapper around a boto3 DynamoDB Table resource that auto-records
latency and errors for every operation using your registry metrics.

Usage:
    import boto3
    from shared.metrics.dynamo_tracker import TrackedDynamoTable

    _raw_table = boto3.resource("dynamodb").Table("ibts-txn")
    table      = TrackedDynamoTable(
                     _raw_table,
                     table_name = "ibts-txn",
                     service    = "payment-switch",
                 )

    # Use exactly like a normal boto3 Table:
    item   = table.get_item(Key={"txn_id": txn_id})
    table.put_item(Item=txn.dict())
    table.update_item(Key=..., UpdateExpression=...)
    rows   = table.query(IndexName="idempotency-index", ...)
"""

import time
from typing import Any

from .registry import (
    DYNAMO_OP_LATENCY_SECONDS,
    DYNAMO_ERRORS_TOTAL,
)

# Maps our operation names to the L_OPERATION label values in the registry
# operation: GetItem | PutItem | UpdateItem | Query | DeleteItem | Scan
_OP_LABELS = {
    "get_item":    "GetItem",
    "put_item":    "PutItem",
    "update_item": "UpdateItem",
    "query":       "Query",
    "delete_item": "DeleteItem",
    "scan":        "Scan",
}


class TrackedDynamoTable:
    """
    Drop-in replacement for a boto3 DynamoDB Table.
    Every method records:
      - ibts_dynamo_operation_latency_seconds  (always)
      - ibts_dynamo_errors_total               (on exception, labeled with AWS error code)
    """

    def __init__(self, table, table_name: str, service: str):
        self._table      = table
        self._table_name = table_name
        self._service    = service

    # ── Internal dispatcher ────────────────────────────────────────────────────
    def _call(self, method_name: str, **kwargs) -> Any:
        """
        Call the underlying boto3 Table method, record latency + errors.
        boto3 DynamoDB calls are synchronous — wrap in asyncio.to_thread
        if you need async context.
        """
        operation = _OP_LABELS.get(method_name, method_name)
        start     = time.perf_counter()

        try:
            result = getattr(self._table, method_name)(**kwargs)
            return result

        except Exception as exc:
            # Extract AWS error code if available e.g. ProvisionedThroughputExceeded
            error_type = type(exc).__name__
            try:
                error_type = exc.response["Error"]["Code"]   # boto3 ClientError
            except (AttributeError, KeyError, TypeError):
                pass

            DYNAMO_ERRORS_TOTAL.labels(
                service    = self._service,
                table      = self._table_name,
                error_type = error_type,
            ).inc()
            raise

        finally:
            DYNAMO_OP_LATENCY_SECONDS.labels(
                service   = self._service,
                table     = self._table_name,
                operation = operation,
            ).observe(time.perf_counter() - start)

    # ── Public methods — mirror boto3 Table API exactly ────────────────────────
    def get_item(self, **kwargs) -> dict:
        return self._call("get_item", **kwargs)

    def put_item(self, **kwargs) -> dict:
        return self._call("put_item", **kwargs)

    def update_item(self, **kwargs) -> dict:
        return self._call("update_item", **kwargs)

    def delete_item(self, **kwargs) -> dict:
        return self._call("delete_item", **kwargs)

    def query(self, **kwargs) -> dict:
        return self._call("query", **kwargs)

    def scan(self, **kwargs) -> dict:
        return self._call("scan", **kwargs)

    # ── Convenience: paginated query (returns all Items across pages) ──────────
    def query_all(self, **kwargs) -> list:
        """
        Calls query() repeatedly until LastEvaluatedKey is exhausted.
        Each page records its own latency observation.
        Useful for GSI lookups that may span multiple pages.
        """
        items      = []
        last_key   = None

        while True:
            if last_key:
                kwargs["ExclusiveStartKey"] = last_key

            response = self.query(**kwargs)
            items.extend(response.get("Items", []))
            last_key = response.get("LastEvaluatedKey")

            if not last_key:
                break

        return items
